s<-fread(file.path(OUT,'01_LLPS_stratification/highlow_technical_covariates.csv'))[method=='within_median'&clinical_group!='Normal'];w<-dcast(s,specimen_id+patient_id+dataset~state,value.var=c('log_count_mean','log_feature_mean','score_mean'));w[,`:=`(depth_difference=log_count_mean_high-log_count_mean_low,feature_difference=log_feature_mean_high-log_feature_mean_low,score_difference=score_mean_high-score_mean_low)];w<-w[,.(depth_difference=median(depth_difference),feature_difference=median(feature_difference),score_difference=median(score_difference)),by=.(patient_id,dataset)];p<-fread(file.path(OUT,'03_patient_level_comparison/within_median_t10_patient_pairs.csv.gz'))[kind=='network'&analysis_condition=='Tumor'];p<-merge(p,w,by=c('patient_id','dataset'));stat<-p[,{
 X<-if(uniqueN(dataset)>1)model.matrix(~depth_difference+feature_difference+factor(dataset),.SD)else model.matrix(~depth_difference+feature_difference,.SD);rk<-qr(X)$rank;df<-.N-rk;est<-pv<-NA_real_;if(.N>=5&&rk==ncol(X)&&df>=3){fit<-lm.fit(X,difference);se<-sqrt(sum(fit$residuals^2)/df*diag(solve(crossprod(X))));est<-fit$coefficients[1];pv<-2*pt(-abs(est/se[1]),df=df)};list(n_patients=.N,unadjusted_median_difference=median(difference),difference_depth_r=if(sd(depth_difference)>1e-8&&sd(difference)>1e-8)cor(difference,depth_difference)else NA_real_,difference_feature_r=if(sd(feature_difference)>1e-8&&sd(difference)>1e-8)cor(difference,feature_difference)else NA_real_,adjusted_reference_intercept=est,p=pv,model_rank=rk,residual_df=df,depth_range_min=min(depth_difference),depth_range_max=max(depth_difference))
},by=.(direction,partner)];stat[,FDR:=p.adjust(p,'BH'),by=direction];stat[,interpretation:='Exploratory extrapolation to zero depth/feature difference in reference dataset; not a causal adjusted CellChat effect. Inspect range and df.'];writecsv(stat,file.path(OUT,'07_sensitivity_analysis/communication_depth_sensitivity.csv'));writecsv(p,file.path(OUT,'07_sensitivity_analysis/communication_depth_patient_data.csv'));cat('COMMUNICATION DEPTH COMPLETE\n')
